try {
  const items = $('Gmail Trigger').all();
  const configRows = $('Load Config').all();
  const config = {};
  for (const row of configRows) {
    config[row.json.klucz] = row.json.wartosc;
  }
  const BODY_LIMIT = parseInt(config.body_limit) || 3000;
  const SUBJECT_LIMIT = parseInt(config.subject_limit) || 200;

  // === IDEMPOTENCY CHECK ===
  // Cache 500 ostatnich messageId w workflow static data
  // Chroni przed duplikatami przy re-trigger lub powtórnym pollu Gmail
  const staticData = $getWorkflowStaticData('global');
  if (!Array.isArray(staticData.processedIds)) staticData.processedIds = [];

  const results = [];
  let skippedDuplicates = 0;

  for (const item of items) {
    const email = item.json;
    const messageId = email.id || email.messageId || '';

    // Skip duplikatów (idempotency guard)
    if (messageId && staticData.processedIds.includes(messageId)) {
      skippedDuplicates++;
      continue;
    }

    const subject = (email.subject || email.Subject || '').trim();
    const textBody = (email.body || email.textPlain || email.text || email.snippet || '').trim();
    const htmlBody = (email.textHtml || email.html || '').trim();
    const body = textBody || htmlBody.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
    const rawFrom = email.From || email.from || '';
    const from = (typeof rawFrom === 'string') ? rawFrom.replace(/.*<(.+)>.*/, '$1').trim() : (rawFrom?.value?.[0]?.address || '');
    const fromName = (typeof rawFrom === 'string') ? rawFrom.replace(/<.*>/, '').replace(/"/g, '').trim() : (rawFrom?.value?.[0]?.name || '');
    const threadId = email.threadId || '';
    const date = email.date || email.Date || new Date().toISOString();

    if (!from) {
      throw new Error(`Email validation failed: brak adresu nadawcy. MessageId: ${messageId}`);
    }

    // Mark as processed AFTER validation passes (clean state on early throws)
    if (messageId) {
      staticData.processedIds.push(messageId);
      // Keep only last 500 entries to prevent unbounded growth
      if (staticData.processedIds.length > 500) {
        staticData.processedIds = staticData.processedIds.slice(-500);
      }
    }

    const hasContent = subject || body;
    results.push({
      json: {
        messageId,
        threadId,
        subject: subject.substring(0, SUBJECT_LIMIT) || '(brak tematu)',
        body: body.substring(0, BODY_LIMIT) || '(brak treści)',
        bodyLength: body.length,
        from,
        fromName,
        date,
        isEmpty: !hasContent,
        isTruncated: body.length > BODY_LIMIT
      }
    });
  }

  if (skippedDuplicates > 0) {
    console.log(`[Validate Email] Skipped ${skippedDuplicates} duplicate messageId(s) via idempotency cache`);
  }

  return results;
} catch (error) {
  const enriched = new Error(`[Validate Email] ${error.message}`);
  enriched.description = `Node: Validate Email\nOriginal: ${error.message}`;
  throw enriched;
}

try {
const routeData = $('Validate and Route').first().json;
const draftRaw = $('AI Generate Draft').first().json;
const draftText = draftRaw.text || draftRaw.output || draftRaw.response || 'Nie udało się wygenerować draftu';

const categoryLabel = routeData.categoryLabel;
const urgencyIcon = routeData.isUrgent ? '🔴 PILNE' : '🟢 Normalne';

let warnings = [];
try {
  if ($('Gmail - Add Label').first().json.error) warnings.push('⚠ ️ Nie udało się dodać etykiety');
} catch(e) { warnings.push('⚠ ️ Nie udało się dodać etykiety'); }
try {
  if ($('Gmail - Create Draft').first().json.error) warnings.push('⚠ ️ Nie udało się utworzyć draftu');
} catch(e) { warnings.push('⚠ ️ Nie udało się utworzyć draftu'); }
if (routeData._parseError) {
  warnings.push('⚠ ️ AI fallback â€” kategoria na podstawie słów kluczowych');
}
const warningText = warnings.length > 0 ? '\n' + warnings.join('\n') : '';

const msg = `${routeData.isUrgent ? '🔴 **PILNE** 🔴\n' : ''}**${categoryLabel}** | ${urgencyIcon}

**Od:** ${routeData.fromName} <${routeData.from}>
**Temat:** ${routeData.subject}
**Przypisano:** ${routeData.assignedPerson} (${routeData.assignedRole})

**Podsumowanie:**
${routeData.summary}
${routeData.isUrgent ? '\n**Powód pilności:** ' + routeData.urgencyReason : ''}${warningText}

---
**Draft odpowiedzi:**
${draftText.substring(0, 1500)}`;

return [{
  json: { ...routeData, draftText, notificationMessage: msg, warnings }
}];
} catch (error) {
  return [{
    json: {
      _error: true, _errorNode: 'Format Notification',
      _errorMessage: error.message,
      ...($input.first()?.json || {})
    }
  }];
}

try {
