const assignedSlackId = data.assignedSlackUserId;

if (!assignedSlackId) {
  throw new Error(`Brak Slack ID dla: ${data.assignedPerson}. Uzupełnij slack_user_id w arkuszu Zespół.`);
}

const crisisSlackId = data.crisisManager?.slackUserId || '';

const slackMessage = `${data.isUrgent ? '🔴 PILNE â€” ' : ''}**${data.categoryLabel}**

**Od:** ${data.fromName} <${data.from}>
**Temat:** ${data.subject}
**Podsumowanie:** ${data.summary}
${data.isUrgent ? '**Powód pilności:** ' + data.urgencyReason : ''}

Draft odpowiedzi zapisany w Gmail â€” przejrzyj i wyślij ręcznie.`;

const result = [{
  json: { ...data, slackUserId: assignedSlackId, slackMessage }
}];

if (data.isUrgent && crisisSlackId && crisisSlackId !== assignedSlackId) {
  result.push({
    json: {
      ...data, slackUserId: crisisSlackId,
      slackMessage: `🔴 **PILNA SPRAWA â€” wymagana natychmiastowa reakcja!**\n\n${slackMessage}`
    }
  });
}
return result;
} catch (error) {
  const enriched = new Error(`[Prepare Slack DM] ${error.message}`);
  enriched.description = `Node: Prepare Slack DM\nOriginal: ${error.message}`;
  throw enriched;
}

