try {
const webhookData = $input.first().json;
const prevData = $('Prepare Approval Email').first().json;

// Read action from query parameter (e.g. ?action=zatwierdz)
const query = webhookData.query || webhookData.req?.query || {};
const action = query.action || 'unknown';

// Check timeout (no webhook data = expired)
const isTimeout = !webhookData.req && !webhookData.query && !query.action;

return [{
  json: {
    ...prevData,
    decision: isTimeout ? 'timeout' : action,
    isApproved: action === 'zatwierdz',
    decidedAt: new Date().toISOString()
  }
}];
} catch (error) {
  return [{ json: { ...($input.first()?.json || {}), decision: 'error', _errorMessage: error.message } }];
}

