try {
const aiOutput = $input.first().json;
const emailData = $('Validate Email').first().json;

// === LOAD CONFIG ===
const configRows = $('Load Config').all();
const config = {};
for (const row of configRows) {
  config[row.json.klucz] = row.json.wartosc;
}

const teamRows = $('Load Zespol').all();
const teamMap = {};
for (const row of teamRows) {
  const r = row.json;
  teamMap[r.kategoria] = {
    person: r.osoba, role: r.rola, channel: r.slack_channel,
    slackUserId: r.slack_user_id, gmailLabelId: r.gmail_label_id, emoji: r.emoji
  };
}

const catRows = $('Load Kategorie').all();
const validCategories = [];
const categoryLabels = {};
for (const row of catRows) {
  const r = row.json;
  validCategories.push(r.klucz);
  categoryLabels[r.klucz] = `${r.emoji} ${r.nazwa_pl}`;
}

// === PARSE AI RESPONSE ===
let aiResult;
let parseError = false;
let errorReason = '';

try {
  if (aiOutput.output && typeof aiOutput.output === 'object') {
    aiResult = aiOutput.output;
  } else if (aiOutput.output && typeof aiOutput.output === 'string') {
    aiResult = JSON.parse(aiOutput.output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } else if (aiOutput.text && typeof aiOutput.text === 'string') {
    aiResult = JSON.parse(aiOutput.text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } else if (aiOutput.category) {
    aiResult = aiOutput;
  } else {
    throw new Error('Unexpected AI output format');
  }

  const defaultCat = config.default_category || 'pytanie_klienta';
  if (!validCategories.includes(aiResult.category)) {
    errorReason = `Nieznana kategoria: ${aiResult.category}`;
    aiResult.category = defaultCat;
    aiResult.summary = (aiResult.summary || '') + ' [AUTO-FALLBACK]';
    parseError = true;
  }
  if (!['pilne', 'normalne'].includes(aiResult.urgency)) {
    aiResult.urgency = 'normalne';
  }
} catch (e) {
  parseError = true;
  errorReason = e.message;

  // === KEYWORD FALLBACK ===
  const fullText = ((emailData.subject || '') + ' ' + (emailData.body || '')).toLowerCase();
  const urgentKw = ['pilne','pilna','asap','natychmiast','krytyczne','deadline','awaria','nie działa','windykacja','do jutra','w ciągu 24','natychmiastow'];
  const isUrgentFB = urgentKw.some(kw => fullText.includes(kw));

  let fbCat = 'pytanie_klienta';
  if (fullText.includes('faktur') || fullText.includes('płatnoś') || fullText.includes('korekta')) fbCat = 'sprawy_fakturowe';
  else if (fullText.includes('reklamac') || fullText.includes('rozczarowan')) fbCat = 'reklamacja_eskalacja';
  else if (fullText.includes('ofert') || fullText.includes('wycen') || fullText.includes('cennik')) fbCat = 'zapytanie_ofertowe';
  else if (fullText.includes('cv') || fullText.includes('aplikac') || fullText.includes('stanowisko')) fbCat = 'rekrutacja_cv';
  else if (fullText.includes('unsubscribe') || fullText.includes('kliknij tutaj')) fbCat = 'spam';
  else if (fullText.includes('out of office') || fullText.includes('no-reply') || fullText.includes('noreply')) fbCat = 'wiadomosc_systemowa';
  else if (fullText.includes('umow') || fullText.includes('nda') || fullText.includes('prawny') || fullText.includes('kancelari')) fbCat = 'sprawy_prawne_umowy';
  else if (fullText.includes('konsorcj') || fullText.includes('partnerst') || fullText.includes('współprac')) fbCat = 'wspolpraca_partnerstwo';
  else if (fullText.includes('konferencj') || fullText.includes('zaproszeni') || fullText.includes('webinar')) fbCat = 'zaproszenie_wydarzenie';

  aiResult = {
    category: fbCat, urgency: isUrgentFB ? 'pilne' : 'normalne',
    summary: `[FALLBACK - AI error: ${errorReason}] Kategoria na podstawie słów kluczowych.`,
    key_entities: [], urgency_reason: isUrgentFB ? 'Wykryto słowa kluczowe pilności' : ''
  };
}

// === ROUTING ===
const defaultCategory = config.default_category || 'pytanie_klienta';
const routing = teamMap[aiResult.category] || teamMap[defaultCategory] || {
  person: config.crisis_manager_name, role: config.crisis_manager_role,
  channel: config.normal_channel, slackUserId: config.crisis_slack_id,
  gmailLabelId: '', emoji: '❓'
};

const isUrgent = aiResult.urgency === 'pilne';
const crisisManager = isUrgent ? {
  person: config.crisis_manager_name,
  role: config.crisis_manager_role,
  slackUserId: config.crisis_slack_id
} : null;

return [{
  json: {
    messageId: emailData.messageId, threadId: emailData.threadId,
    subject: emailData.subject, body: emailData.body,
    from: emailData.from, fromName: emailData.fromName, date: emailData.date,
    category: aiResult.category,
    categoryLabel: categoryLabels[aiResult.category] || `❓ ${aiResult.category}`,
    urgency: aiResult.urgency, isUrgent,
    summary: aiResult.summary || 'Brak podsumowania',
    keyEntities: aiResult.key_entities || [],
    urgencyReason: aiResult.urgency_reason || '',
    assignedPerson: routing.person, assignedRole: routing.role,
    assignedChannel: routing.channel, assignedSlackUserId: routing.slackUserId,
    gmailLabelId: routing.gmailLabelId, emoji: routing.emoji,
    crisisManager,
    _parseError: parseError, _errorReason: errorReason,
    _config: config, _categoryLabels: categoryLabels
  }
}];
} catch (error) {
  const enriched = new Error(`[Validate & Route] ${error.message}`);
  enriched.description = `Node: Validate & Route\nOriginal: ${error.message}`;
  throw enriched;
}
